static int do_dump(const json_t *json, size_t flags, int depth, hashtable_t *parents,
                   json_dump_callback_t dump, void *data) {
    int embed = flags & JSON_EMBED;

    flags &= ~JSON_EMBED;

    if (!json)
        return -1;

    if (depth >= JSON_PARSER_MAX_DEPTH)
        return -1;

for (i = 0; i < n - 1; ++i) {
    if (do_dump(json_array_get(json, i), flags, depth + 1, parents, dump,
                data))
        return -1;

    if (dump(",", 1, data) || dump_indent(flags, depth + 1, 1, dump, data))
        return -1;
}

if (do_dump(json_array_get(json, i), flags, depth + 1, parents, dump, data))
    return -1;

static void max_depth() {
    json_t *json;
    char *result;

    /* A structure nested exactly to the limit must still serialize. */
    json = build_nested_array(JSON_PARSER_MAX_DEPTH);
    result = json_dumps(json, 0);
    if (!result)
        fail("json_dumps failed for a structure within the depth limit");
    free(result);
    json_decref(json);

    /* A structure nested deeper than the limit must fail cleanly rather
       than overflow the stack. */
    json = build_nested_array(JSON_PARSER_MAX_DEPTH + 100);
    if (json_dumps(json, 0) != NULL)
        fail("json_dumps didn't fail for a too deeply nested structure");
    json_decref(json);
}

static json_t *parse_value(lex_t *lex, size_t flags, json_error_t *error) {
    json_t *json;

    lex->depth++;
    if (lex->depth > JSON_PARSER_MAX_DEPTH) {
        error_set(error, lex, json_error_stack_overflow, "maximum parsing depth reached");
        return NULL;
    }

static json_t *parse_json(lex_t *lex, size_t flags, json_error_t *error) {
    json_t *result;

    lex->depth = 0;

    lex_scan(lex, error);
    if (!(flags & JSON_DECODE_ANY)) {
        if (lex->token != '[' && lex->token != '{') {
            error_set(error, lex, json_error_invalid_syntax, "'[' or '{' expected");
            return NULL;
        }
    }

    result = parse_value(lex, flags, error);
    if (!result)
        return NULL;

    if (!(flags & JSON_DISABLE_EOF_CHECK)) {
        lex_scan(lex, error);
        if (lex->token != TOKEN_EOF) {
            error_set(error, lex, json_error_end_of_input_expected,
                      "end of file expected");
            json_decref(result);
            return NULL;
        }
    }

int json_dump_callback(const json_t *json, json_dump_callback_t callback, void *data,
                       size_t flags) {
    int res;
    hashtable_t parents_set;

    if (!(flags & JSON_ENCODE_ANY)) {
        if (!json_is_array(json) && !json_is_object(json))
            return -1;
    }

    if (hashtable_init(&parents_set))
        return -1;
    res = do_dump(json, flags, 0, &parents_set, callback, data);
    hashtable_close(&parents_set);

    return res;
}

char *json_dumps(const json_t *json, size_t flags) {
    strbuffer_t strbuff;
    char *result;

    if (strbuffer_init(&strbuff))
        return NULL;

    if (json_dump_callback(json, dump_to_strbuffer, (void *)&strbuff, flags))
        result = NULL;
    else {
        char *new_result;
        result = strbuffer_steal_value(&strbuff);
        // technically the resizing is not needed.
        new_result = jsonp_realloc(result, strbuff.size, strbuff.length + 1);
        if (new_result) { // when realloc fails we just use the original pointer
            result = new_result;
        }
    }

    strbuffer_close(&strbuff);
    return result;

